<?php
declare(strict_types=1);
if(session_status()!==PHP_SESSION_ACTIVE)session_start();
$root=dirname(__DIR__,3);$cfg=require $root.'/config.php';
if(empty($_SESSION['user'])){header('Location:index.php');exit;}
require_once $root.'/app/Core/UnifiedSidebar.php';
date_default_timezone_set($cfg['timezone']??'America/Argentina/Buenos_Aires');
function de($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function dgo(string $url):never{header('Location:'.$url);exit;}
function dcsrf():void{if(!hash_equals((string)($_SESSION['csrf']??''),(string)($_POST['csrf']??''))){http_response_code(419);exit('La sesión venció. Volvé atrás y reintentá.');}}
function dqty($v):string{return rtrim(rtrim(number_format((float)$v,3,',','.'),'0'),',');}
$db=new PDO('mysql:host='.$cfg['db_host'].';dbname='.$cfg['db_name'].';charset=utf8mb4',$cfg['db_user'],$cfg['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
$db->exec("CREATE TABLE IF NOT EXISTS delivery_notes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,delivery_number VARCHAR(40) NULL UNIQUE,quote_id INT UNSIGNED NOT NULL,project_id INT UNSIGNED NOT NULL,location_id INT UNSIGNED NOT NULL,delivery_date DATE NOT NULL,status ENUM('borrador','confirmado','anulado') NOT NULL DEFAULT 'borrador',recipient_name VARCHAR(190) NULL,recipient_document VARCHAR(40) NULL,delivery_address VARCHAR(255) NULL,notes TEXT NULL,confirmed_at DATETIME NULL,created_by INT UNSIGNED NULL,confirmed_by INT UNSIGNED NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_delivery_quote(quote_id,status),INDEX idx_delivery_project(project_id,delivery_date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$db->exec("CREATE TABLE IF NOT EXISTS delivery_note_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,delivery_note_id BIGINT UNSIGNED NOT NULL,quote_item_id INT UNSIGNED NOT NULL,product_id INT UNSIGNED NULL,sku VARCHAR(190) NULL,description VARCHAR(255) NOT NULL,unit VARCHAR(60) NOT NULL DEFAULT 'Unidad',quantity DECIMAL(15,3) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_delivery_quote_item(delivery_note_id,quote_item_id),INDEX idx_delivery_item_product(product_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));
$a=$_GET['a']??'deliveries';$msg=$_SESSION['msg']??null;unset($_SESSION['msg']);
try{
 if($a==='save_delivery'){
  dcsrf();$qid=(int)($_POST['quote_id']??0);$location=(int)($_POST['location_id']??0);$date=(string)($_POST['delivery_date']??'');$quantities=$_POST['qty']??[];
  $s=$db->prepare("SELECT id,project_id,status FROM quotes WHERE id=? AND status IN ('aprobado_definitivo','final')");$s->execute([$qid]);$q=$s->fetch();if(!$q)throw new Exception('El presupuesto debe estar aceptado definitivamente.');if(!$location||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))throw new Exception('Elegí depósito y fecha.');
  $s=$db->prepare("SELECT qi.*,COALESCE((SELECT SUM(dni.quantity) FROM delivery_note_items dni JOIN delivery_notes dn ON dn.id=dni.delivery_note_id WHERE dni.quote_item_id=qi.id AND dn.status='confirmado'),0) delivered FROM quote_items qi WHERE qi.quote_id=? AND qi.product_id IS NOT NULL AND qi.is_concept=0 AND COALESCE(qi.sku,'') NOT IN ('__CONCEPT__','__CONCEPT_TOTAL__') ORDER BY qi.block_order,qi.sort_order,qi.id");$s->execute([$qid]);$available=$s->fetchAll();$chosen=[];
  foreach($available as $item){$pending=max(0,(float)$item['quantity']-(float)$item['delivered']);$qty=max(0,(float)($quantities[$item['id']]??0));if($qty>$pending+.0001)throw new Exception('La cantidad de '.$item['description'].' supera lo pendiente.');if($qty>0)$chosen[]=[$item,$qty];}if(!$chosen)throw new Exception('Ingresá al menos una cantidad a entregar.');
  $db->beginTransaction();$db->prepare('INSERT INTO delivery_notes(quote_id,project_id,location_id,delivery_date,recipient_name,recipient_document,delivery_address,notes,created_by) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$qid,$q['project_id'],$location,$date,trim((string)($_POST['recipient_name']??'')),trim((string)($_POST['recipient_document']??'')),trim((string)($_POST['delivery_address']??'')),trim((string)($_POST['notes']??'')),(int)$_SESSION['user']['id']]);$id=(int)$db->lastInsertId();$number='REM-'.date('Y',strtotime($date)).'-'.str_pad((string)$id,6,'0',STR_PAD_LEFT);$db->prepare('UPDATE delivery_notes SET delivery_number=? WHERE id=?')->execute([$number,$id]);$ins=$db->prepare('INSERT INTO delivery_note_items(delivery_note_id,quote_item_id,product_id,sku,description,unit,quantity) VALUES(?,?,?,?,?,?,?)');foreach($chosen as [$item,$qty])$ins->execute([$id,$item['id'],$item['product_id'],$item['sku'],$item['description'],$item['unit'],$qty]);$db->commit();$_SESSION['msg']='Remito '.$number.' preparado. Revisalo y confirmalo para descontar stock.';dgo('?a=delivery&id='.$id);
 }
 if($a==='confirm_delivery'){
  dcsrf();$id=(int)($_POST['id']??0);$db->beginTransaction();$s=$db->prepare('SELECT dn.*,il.name location_name FROM delivery_notes dn JOIN inventory_locations il ON il.id=dn.location_id WHERE dn.id=? FOR UPDATE');$s->execute([$id]);$note=$s->fetch();if(!$note||$note['status']!=='borrador')throw new Exception('El remito no está disponible para confirmar.');$s=$db->prepare('SELECT dni.*,COALESCE(ii.track_stock,p.track_stock) track_stock,COALESCE(ii.allow_negative,0) allow_negative FROM delivery_note_items dni JOIN products p ON p.id=dni.product_id LEFT JOIN inventory_items ii ON ii.product_id=dni.product_id WHERE dni.delivery_note_id=?');$s->execute([$id]);$items=$s->fetchAll();
  foreach($items as $item){$pending=$db->prepare("SELECT qi.quantity-COALESCE((SELECT SUM(oi.quantity) FROM delivery_note_items oi JOIN delivery_notes od ON od.id=oi.delivery_note_id WHERE oi.quote_item_id=qi.id AND od.status='confirmado'),0) FROM quote_items qi WHERE qi.id=? FOR UPDATE");$pending->execute([$item['quote_item_id']]);if((float)$item['quantity']>(float)$pending->fetchColumn()+.0001)throw new Exception('La entrega supera la cantidad pendiente de '.$item['description'].'. Actualizá el remito.');if(!$item['track_stock'])continue;$db->prepare('INSERT IGNORE INTO inventory_balances(product_id,location_id,quantity) VALUES(?,?,0)')->execute([$item['product_id'],$note['location_id']]);$lock=$db->prepare('SELECT quantity FROM inventory_balances WHERE product_id=? AND location_id=? FOR UPDATE');$lock->execute([$item['product_id'],$note['location_id']]);$current=(float)$lock->fetchColumn();$new=$current-(float)$item['quantity'];if($new<-.0001&&!$item['allow_negative'])throw new Exception('Stock insuficiente para '.$item['description'].' en '.$note['location_name'].'. Disponible: '.dqty($current).'.');$db->prepare('UPDATE inventory_balances SET quantity=? WHERE product_id=? AND location_id=?')->execute([$new,$item['product_id'],$note['location_id']]);$db->prepare("INSERT INTO inventory_movements(product_id,location_id,movement_date,movement_type,quantity,source_module,reference_type,reference_id,document_number,notes,user_id) VALUES(?,?,?,'salida',?,'proyectos','delivery_note',?,?,?,?)")->execute([$item['product_id'],$note['location_id'],$note['delivery_date'],-(float)$item['quantity'],$id,$note['delivery_number'],'Entrega de materiales del proyecto',(int)$_SESSION['user']['id']]);$db->prepare('UPDATE products SET stock_quantity=(SELECT COALESCE(SUM(quantity),0) FROM inventory_balances WHERE product_id=?) WHERE id=?')->execute([$item['product_id'],$item['product_id']]);}
  $db->prepare("UPDATE delivery_notes SET status='confirmado',confirmed_at=NOW(),confirmed_by=? WHERE id=?")->execute([(int)$_SESSION['user']['id'],$id]);$db->commit();$_SESSION['msg']='Entrega confirmada. El stock fue descontado una sola vez.';dgo('?a=delivery&id='.$id);
 }
}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$_SESSION['msg']='No se pudo completar la operación: '.$e->getMessage();dgo($_SERVER['HTTP_REFERER']??'?a=deliveries');}

if($a==='new_delivery'){
 $qid=(int)($_GET['quote_id']??0);$s=$db->prepare("SELECT q.*,p.project_number,p.name project_name,c.business_name,c.contact_name,c.address,c.city,c.province FROM quotes q JOIN projects p ON p.id=q.project_id JOIN clients c ON c.id=p.client_id WHERE q.id=? AND q.status IN ('aprobado_definitivo','final')");$s->execute([$qid]);$quote=$s->fetch();if(!$quote){http_response_code(422);exit('Este presupuesto todavía no está aceptado definitivamente.');}$s=$db->prepare("SELECT qi.*,COALESCE((SELECT SUM(dni.quantity) FROM delivery_note_items dni JOIN delivery_notes dn ON dn.id=dni.delivery_note_id WHERE dni.quote_item_id=qi.id AND dn.status='confirmado'),0) delivered FROM quote_items qi WHERE qi.quote_id=? AND qi.product_id IS NOT NULL AND qi.is_concept=0 AND COALESCE(qi.sku,'') NOT IN ('__CONCEPT__','__CONCEPT_TOTAL__') ORDER BY qi.block_order,qi.sort_order,qi.id");$s->execute([$qid]);$items=array_values(array_filter($s->fetchAll(),fn($i)=>(float)$i['quantity']-(float)$i['delivered']>.0001));$locations=$db->query('SELECT * FROM inventory_locations WHERE active=1 ORDER BY is_default DESC,name')->fetchAll();$address=trim(implode(', ',array_filter([$quote['address'],$quote['city'],$quote['province']])));
 dhead('Nueva entrega','new_delivery',$msg);?><div class="actions"><div style="flex:1"><a href="?a=quote_state_edit&id=<?=$qid?>">← Volver al presupuesto</a><h1>Preparar entrega de materiales</h1><p class="muted"><?=de($quote['project_number'].' · '.$quote['project_name'].' · '.$quote['business_name'])?></p></div></div><?php if(!$items):?><div class="card"><h2>Todo entregado</h2><p>No quedan materiales pendientes en este presupuesto.</p></div><?php else:?><form method="post" action="?a=save_delivery"><input type="hidden" name="csrf" value="<?=de($_SESSION['csrf'])?>"><input type="hidden" name="quote_id" value="<?=$qid?>"><div class="card grid"><p class="c4"><label>Fecha de entrega / retiro</label><input type="date" name="delivery_date" value="<?=date('Y-m-d')?>" required></p><p class="c4"><label>Depósito de salida</label><select name="location_id" required><?php foreach($locations as $l):?><option value="<?=$l['id']?>"><?=de($l['name'])?></option><?php endforeach;?></select></p><p class="c4"><label>Recibe</label><input name="recipient_name" value="<?=de($quote['contact_name'])?>"></p><p class="c4"><label>DNI / documento</label><input name="recipient_document"></p><p class="c8"><label>Dirección de entrega</label><input name="delivery_address" value="<?=de($address)?>"></p></div><div class="card scroll"><h2>Materiales pendientes</h2><table><tr><th>Código</th><th>Producto</th><th>Presupuestado</th><th>Ya entregado</th><th>A entregar ahora</th></tr><?php foreach($items as $i):$pending=(float)$i['quantity']-(float)$i['delivered'];?><tr><td><?=de($i['sku'])?></td><td><b><?=de($i['description'])?></b><br><span class="muted"><?=de($i['unit'])?></span></td><td><?=dqty($i['quantity'])?></td><td><?=dqty($i['delivered'])?></td><td><input style="max-width:140px" type="number" min="0" max="<?=$pending?>" step=".001" name="qty[<?=$i['id']?>]" value="<?=$pending?>"></td></tr><?php endforeach;?></table><p><label>Observaciones</label><textarea name="notes" placeholder="Estado de bultos, retiro parcial, persona autorizada, etc."></textarea></p><button class="btn">Generar remito borrador</button></div></form><?php endif;dfoot();exit;
}

if(in_array($a,['delivery','delivery_print'],true)){
 $id=(int)($_GET['id']??0);$s=$db->prepare('SELECT dn.*,q.version_no,q.proposal_name,p.project_number,p.name project_name,c.business_name,c.cuit,il.name location_name,u.name created_name,uc.name confirmed_name FROM delivery_notes dn JOIN quotes q ON q.id=dn.quote_id JOIN projects p ON p.id=dn.project_id JOIN clients c ON c.id=p.client_id JOIN inventory_locations il ON il.id=dn.location_id LEFT JOIN users u ON u.id=dn.created_by LEFT JOIN users uc ON uc.id=dn.confirmed_by WHERE dn.id=?');$s->execute([$id]);$note=$s->fetch();if(!$note){http_response_code(404);exit('Remito inexistente.');}$s=$db->prepare('SELECT * FROM delivery_note_items WHERE delivery_note_id=? ORDER BY id');$s->execute([$id]);$items=$s->fetchAll();$print=$a==='delivery_print';dhead('Remito '.$note['delivery_number'],$print?'delivery_print':'delivery',$msg,$print);?><div class="paper"><div class="doc-head"><div><img src="assets/punto-domotica-logo.svg" alt="Punto Domótica"><p class="muted">Entrega de materiales / documento no fiscal</p></div><div class="doc-number"><b>REMITO</b><strong><?=de($note['delivery_number'])?></strong><span><?=de(date('d/m/Y',strtotime($note['delivery_date'])))?></span></div></div><div class="info"><div><small>CLIENTE</small><b><?=de($note['business_name'])?></b><span>CUIT/DNI: <?=de($note['cuit']?:'—')?></span></div><div><small>PROYECTO</small><b><?=de($note['project_number'].' · '.$note['project_name'])?></b><span>Presupuesto v<?=de($note['version_no'])?></span></div><div><small>SALIDA</small><b><?=de($note['location_name'])?></b><span><?=de($note['status']==='confirmado'?'Stock descontado':'Borrador sin movimiento de stock')?></span></div></div><table><thead><tr><th>Código</th><th>Descripción</th><th>Unidad</th><th class="right">Cantidad</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><?=de($i['sku']?:'—')?></td><td><?=de($i['description'])?></td><td><?=de($i['unit'])?></td><td class="right"><b><?=dqty($i['quantity'])?></b></td></tr><?php endforeach;?></tbody></table><?php if($note['notes']):?><div class="notes"><b>Observaciones</b><br><?=nl2br(de($note['notes']))?></div><?php endif;?><div class="signatures"><div>Entregado por<br><br><b>____________________________</b><br><?=de($note['confirmed_name']?:$note['created_name']?:'Punto Domótica')?></div><div>Recibí conforme<br><br><b>____________________________</b><br><?=de($note['recipient_name']?:'Nombre y firma')?> · <?=de($note['recipient_document']?:'Documento')?></div></div></div><?php if(!$print):?><div class="screen-actions"><a class="btn light" href="?a=deliveries">Volver</a><a class="btn" target="_blank" href="?a=delivery_print&id=<?=$id?>">Imprimir / guardar PDF</a><?php if($note['status']==='borrador'):?><form method="post" action="?a=confirm_delivery" onsubmit="return confirm('¿Confirmar la entrega? Esta acción descontará el stock y no se puede repetir.')"><input type="hidden" name="csrf" value="<?=de($_SESSION['csrf'])?>"><input type="hidden" name="id" value="<?=$id?>"><button class="btn green">Confirmar entrega y descontar stock</button></form><?php endif;?></div><?php else:?><script>window.addEventListener('load',()=>window.print())</script><?php endif;dfoot();exit;
}

$notes=$db->query('SELECT dn.*,p.project_number,p.name project_name,c.business_name,il.name location_name FROM delivery_notes dn JOIN projects p ON p.id=dn.project_id JOIN clients c ON c.id=p.client_id JOIN inventory_locations il ON il.id=dn.location_id ORDER BY dn.delivery_date DESC,dn.id DESC')->fetchAll();$eligible=$db->query("SELECT q.id,q.version_no,q.proposal_name,p.project_number,p.name project_name,c.business_name,COUNT(qi.id) item_count FROM quotes q JOIN projects p ON p.id=q.project_id JOIN clients c ON c.id=p.client_id JOIN quote_items qi ON qi.quote_id=q.id AND qi.product_id IS NOT NULL AND qi.is_concept=0 WHERE q.status IN ('aprobado_definitivo','final') GROUP BY q.id ORDER BY q.quote_date DESC,q.id DESC")->fetchAll();dhead('Entregas de materiales','deliveries',$msg);?><div class="actions"><div style="flex:1"><span class="muted">Logística e inventario</span><h1>Entregas de materiales</h1><p class="muted">Remitos, retiros parciales y trazabilidad de las salidas de stock.</p></div></div><div class="card scroll"><h2>Presupuestos listos para entregar</h2><table><tr><th>Proyecto</th><th>Cliente</th><th>Presupuesto</th><th>Materiales</th><th></th></tr><?php foreach($eligible as $q):?><tr><td><b><?=de($q['project_number'])?></b> · <?=de($q['project_name'])?></td><td><?=de($q['business_name'])?></td><td><?=de($q['proposal_name']?:'Presupuesto')?> · v<?=de($q['version_no'])?></td><td><?=de($q['item_count'])?> ítems</td><td><a class="btn" href="?a=new_delivery&quote_id=<?=$q['id']?>">Preparar entrega</a></td></tr><?php endforeach;?></table><?php if(!$eligible):?><p class="muted">No hay presupuestos aceptados definitivamente con materiales.</p><?php endif;?></div><div class="card scroll"><h2>Historial de remitos</h2><table><tr><th>Número</th><th>Fecha</th><th>Proyecto / cliente</th><th>Depósito</th><th>Estado</th><th></th></tr><?php foreach($notes as $n):?><tr><td><b><?=de($n['delivery_number'])?></b></td><td><?=de(date('d/m/Y',strtotime($n['delivery_date'])))?></td><td><?=de($n['project_number'].' · '.$n['project_name'])?><br><span class="muted"><?=de($n['business_name'])?></span></td><td><?=de($n['location_name'])?></td><td><span class="pill"><?=de($n['status'])?></span></td><td><a class="btn light" href="?a=delivery&id=<?=$n['id']?>">Ver remito</a></td></tr><?php endforeach;?></table><?php if(!$notes):?><p class="muted">Todavía no se generaron remitos.</p><?php endif;?></div><?php dfoot();

function dhead(string $title,string $current,?string $msg,bool $print=false):void{?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=de($title)?> · Punto ERP</title><style><?=erpSidebarCss()?>body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.45 system-ui,-apple-system,Segoe UI,sans-serif}.main{margin-left:var(--sidebar);padding:30px 4%;max-width:1280px}.card,.paper{background:#fff;border:1px solid var(--line);border-radius:14px;padding:22px;margin-bottom:18px}.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:16px}.c4{grid-column:span 4}.c8{grid-column:span 8}.actions,.screen-actions{display:flex;align-items:center;gap:9px;flex-wrap:wrap}.btn{display:inline-flex;border:0;border-radius:8px;padding:10px 14px;background:var(--o);color:#fff;text-decoration:none;font-weight:750;cursor:pointer}.light{background:#edf0f3;color:var(--ink)}.green{background:#18794e}.muted{color:var(--muted)}.pill{display:inline-block;padding:5px 9px;border-radius:20px;background:#edf0f3;font-size:12px}.flash{padding:12px 15px;background:#edf8ef;border:1px solid #bfe0c4;border-radius:9px;margin-bottom:16px}label{display:block;font-weight:700;margin-bottom:5px}input,select,textarea{width:100%;box-sizing:border-box;padding:10px;border:1px solid #cbd1d7;border-radius:8px;font:inherit}textarea{min-height:90px}table{width:100%;border-collapse:collapse}th,td{padding:11px 9px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}th{font-size:11px;text-transform:uppercase;color:var(--muted)}.right{text-align:right}.scroll{overflow:auto}.paper{max-width:900px;margin:0 auto}.doc-head{display:flex;justify-content:space-between;gap:25px;border-bottom:3px solid var(--o);padding-bottom:18px}.doc-head img{width:260px;max-width:100%}.doc-number{text-align:right;display:flex;flex-direction:column}.doc-number b{color:var(--o);font-size:25px}.doc-number strong{font-size:18px}.info{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;padding:20px 0}.info div{display:flex;flex-direction:column}.info small{color:var(--muted);font-weight:800}.notes{margin-top:20px;padding:15px;background:#f6f7f8;border-radius:8px}.signatures{display:grid;grid-template-columns:1fr 1fr;gap:60px;text-align:center;margin-top:70px}.screen-actions{max-width:900px;margin:18px auto}.screen-actions form{margin:0}@media(max-width:900px){.main{margin-left:0;padding:18px 12px}.c4,.c8{grid-column:span 12}.info{grid-template-columns:1fr}.doc-head{flex-direction:column}.doc-number{text-align:left}.signatures{grid-template-columns:1fr;gap:55px}}@media print{body{background:#fff}.sidebar,.mobile-menu-btn,.mobile-topbar,.screen-actions{display:none!important}.main{margin:0;padding:0;max-width:none}.paper{border:0;border-radius:0;padding:8mm;max-width:none}tr{break-inside:avoid}}</style></head><body><?php if(!$print)erpSidebar($current);?><main class="main"><?php if($msg):?><div class="flash"><?=de($msg)?></div><?php endif;}
function dfoot():void{?></main></body></html><?php }
